import sys
sys.path.insert(0,'/tmp/probe/06')
from pnglib import decode_png, get
def load(f):
    w,h,ch,px,_=decode_png(f)
    return w,h,(lambda x,y: get(px,w,ch,x,y)[:3])
# trapezoid kernel: k(i)=H for |i|<=f, linear to 0 at |i|=R; normalized so sum=1. S(x)=255*cumsum.
def trap_step(f, R, n=400):
    # kernel over integer offsets -R..R
    k=[]
    for i in range(-R,R+1):
        ai=abs(i)
        if ai<=f: k.append(1.0)
        else: k.append((R-ai)/(R-f))
    s=sum(k); k=[v/s for v in k]
    # step response: S(x) for integer x, edge at 0.5*(?) -> S(x)=sum_{i: x+0.5+i <= edge...}
    return k
def fit(fpath, axis):
    w,h,c=load(fpath)
    if axis=='h':
        obs=[255-c(x,120)[0] for x in range(10,120)]
        edge0=82
    else:
        obs=[255-c(259,y)[0] for y in range(120,260)]
        edge0=None
    best=None
    for f in range(0,40):
        for R in range(f+1,70):
            k=trap_step(f,R)
            # step response with edge at position e (float): S(p)=255*sum_{i} k[i]*1[p+0.5+i>=e]... use conv with rect
            # S(p) = 255 * sum_{j>=p} ... simpler: S(p)=255*(1 - cdf up to p-e)
            import math
            cum=[0.0]
            for v in k: cum.append(cum[-1]+v)
            # offset of kernel center at index R
            for e10 in range(750,900):
                e=e10/10
                err=0
                for p,d in enumerate(obs):
                    x=p+10 if axis=='h' else p+120
                    # coverage = sum of k over offsets i where p+i+0.5 >= e  (step to the right of e)
                    t = e - (x+0.5) + R  # index into cum
                    ti=int(t); frac=t-ti
                    if ti<0: cov=0.0
                    elif ti>=len(cum)-1: cov=1.0
                    else: cov=cum[ti]+frac*(cum[ti+1]-cum[ti])
                    pred=255*(1-cov)
                    err+=(pred-d)**2
                if best is None or err<best[0]: best=(err,f,R,e)
    print(fpath,axis,"best err=%.1f f=%d R=%d edge=%.2f"%best)
fit('shA10.png','h')
